globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

const edition = globalThis.makeSubjectEdition({"year":2014,"grade":"7-8","title":"Человек и природа","tasksFile":"7-8_2014.pdf","answersFile":"reviewed-7-8.pdf","subject":"chip","contest":"Человек и природа","letters":"АБВГД","count":30,"language":"ru","points":3,"reviewedKey":true}, [{"number":1,"question":"Сколько океанов омывает Северную Америку?","choices":["1","2","3","4","5"],"answer":2,"points":3,"title":"Океаны Северной Америки","steps":["На западе Северной Америки находится Тихий океан, а на востоке — Атлантический. Карибское море относится к Атлантическому бассейну.","Северное побережье омывает Северный Ледовитый океан. Всего у материка берега в трёх океанах."]},{"number":2,"question":"Часть света Азия изображена на рисунке","choices":["","","","",""],"answer":4,"points":3,"title":"Контур Азии","steps":["Ищи восточную часть Евразии. Здесь хорошо выделяются Аравийский полуостров, Индостан и выступы суши на берегу Тихого океана.","У фигуры Д есть эти признаки и отрезана западная часть Евразии. Так показана Азия отдельно от Европы."],"optionFigures":[{"src":"assets/chip/2014/7-8-02-1.webp","detailSrc":"assets/chip/2014/detail/7-8-02-1.webp","width":116,"height":105,"pixelWidth":116,"pixelHeight":105,"alt":"Широкий север, узкий юг и большой остров у юго-востока."},{"src":"assets/chip/2014/7-8-02-2.webp","detailSrc":"assets/chip/2014/detail/7-8-02-2.webp","width":116,"height":105,"pixelWidth":116,"pixelHeight":105,"alt":"Широкий материк с изрезанным западом и несколькими южными полуостровами."},{"src":"assets/chip/2014/7-8-02-3.webp","detailSrc":"assets/chip/2014/detail/7-8-02-3.webp","width":117,"height":105,"pixelWidth":117,"pixelHeight":105,"alt":"Округлый контур с выступом на северо-западе."},{"src":"assets/chip/2014/7-8-02-4.webp","detailSrc":"assets/chip/2014/detail/7-8-02-4.webp","width":116,"height":105,"pixelWidth":116,"pixelHeight":105,"alt":"Компактный контур с несколькими островами рядом."},{"src":"assets/chip/2014/7-8-02-5.webp","detailSrc":"assets/chip/2014/detail/7-8-02-5.webp","width":116,"height":105,"pixelWidth":116,"pixelHeight":105,"alt":"Широкий восточный контур с выступающими полуостровами на юге."}]},{"number":3,"question":"В Южном полушарии направление на юг определяют по созвездию","choices":["Южной Короны","Южного Креста","Микроскопа","Компаса","Стрельца"],"answer":1,"points":3,"title":"Ориентир Южного полушария","steps":["У созвездия Южного Креста можно мысленно провести длинную ось через две звезды. Продолжив ось в сторону нижней звезды, находят область южного полюса неба.","Если опустить из неё направление к горизонту, получим приблизительное направление на юг."]},{"number":4,"question":"Впервые Южного полюса достигли","choices":["испанцы и португальцы под руководством Фернана Магеллана","англичане под руководством Роберта Скотта","русские под руководством Фаддея Фаддеевича Беллинсгаузена","норвежцы под руководством Руаля Амундсена","американцы и эскимосы под руководством Роберта Пири"],"answer":3,"points":3,"title":"Первая экспедиция на полюсе","steps":["До Южного полюса почти одновременно стремились две экспедиции. Норвежцы прибыли в декабре 1911 года, а группа Роберта Скотта добралась туда в январе 1912-го.","Первой достигла полюса команда Руаля Амундсена."]},{"number":5,"question":"С каким современным проливом традиционно связывают путь героев «Одиссеи» между Сциллой и Харибдой?","choices":["Босфор","Ла-Манш","Керченский","Мессинский","Гибралтарский"],"answer":3,"points":3,"title":"Между Сциллой и Харибдой","steps":["Узкий проход в мифе традиционно связывают с морем у южной оконечности Италии.","Сицилию от материковой Италии отделяет Мессинский пролив. Именно его обычно указывают как место описанного эпизода."],"adaptation":"Уточнено, что речь о традиционной локализации мифического эпизода."},{"number":6,"question":"На картине Мартироса Сарьяна изображена высочайшая горная вершина Турции. Это","choices":["Арарат","Джомолунгма","Казбек","Монблан","Улудаг"],"answer":0,"points":3,"title":"Гора Сарьяна","steps":["На картине виден массив с заснеженной вершиной. Мартирос Сарьян неоднократно писал Арарат, который виден из Армении.","Высшая вершина массива, Большой Арарат, находится на территории Турции и поднимается выше 5100 метров."],"figure":{"src":"assets/chip/2014/7-8-06.webp","detailSrc":"assets/chip/2014/detail/7-8-06.webp","width":255,"height":192,"pixelWidth":255,"pixelHeight":192,"alt":"Город и две отдалённые заснеженные вершины в солнечный день."}},{"number":7,"question":"Озеро Байкал замерзает только к началу января, потому что оно","choices":["солёное","тёплое","уникальное","очень большое по площади","обладает огромной массой воды"],"answer":4,"points":3,"title":"Почему Байкал замерзает поздно","steps":["Байкал очень глубок. Большой объём воды запасает за тёплое время много тепла и осенью долго отдаёт его.","Ветер и перемешивание воды тоже могут задержать образование сплошного льда. Среди вариантов главная причина — огромная масса воды."]},{"number":8,"question":"«Учитель задал мне вопрос: Где расположен Канин Нос?» – написано в стихотворении С. Я.Маршака. А действительно – где?","choices":["в Баренцевом море","в Беринговом море","в море Бофорта","в Онежском озере","в море Лаптевых"],"answer":0,"points":3,"title":"Где находится Канин Нос","steps":["Канин Нос — мыс на крайнем северо-западе полуострова Канин. Это район северо-востока европейской части России.","Мыс лежит у перехода от Белого моря к Баренцеву. Из предложенных водоёмов подходит Баренцево море."]},{"number":9,"question":"Печально известный Бермудский треугольник находится","choices":["в Тихом океане в северной части Филиппинского моря","в Тихом океане у побережья Южной Америки","в Индийском океане у побережья острова Ява","в Атлантическом океане у берегов Гвинейского залива","в Атлантическом океане у побережья Багамских островов"],"answer":4,"points":3,"title":"Где находится треугольник","steps":["На карте Бермудские острова находятся в западной части Северной Атлантики. Одну из обычно называемых вершин треугольника помещают у Флориды, другую — около Пуэрто-Рико.","В этом же районе находятся Багамские острова. Подходит вариант об Атлантике вблизи Багам."]},{"number":10,"question":"Какое из этих растений родом из Америки?","choices":["","","","",""],"answer":0,"points":3,"title":"Растение из Америки","steps":["На фотографии А есть продолговатые плоды, характерные для овощного перца рода Capsicum.","Этот род происходит из Америки. После начала плаваний через Атлантику его виды стали выращивать и в других частях света."],"optionFigures":[{"src":"assets/chip/2014/7-8-10-1.webp","detailSrc":"assets/chip/2014/detail/7-8-10-1.webp","width":93,"height":105,"pixelWidth":93,"pixelHeight":105,"alt":"Красные и зелёные продолговатые плоды на кустах."},{"src":"assets/chip/2014/7-8-10-2.webp","detailSrc":"assets/chip/2014/detail/7-8-10-2.webp","width":95,"height":105,"pixelWidth":95,"pixelHeight":105,"alt":"Круглые оранжевые плоды на ветках."},{"src":"assets/chip/2014/7-8-10-3.webp","detailSrc":"assets/chip/2014/detail/7-8-10-3.webp","width":96,"height":105,"pixelWidth":96,"pixelHeight":105,"alt":"Светло-зелёные низкие листовые розетки."},{"src":"assets/chip/2014/7-8-10-4.webp","detailSrc":"assets/chip/2014/detail/7-8-10-4.webp","width":94,"height":105,"pixelWidth":94,"pixelHeight":105,"alt":"Оранжевые плоды плотно прилегают к тонким веткам."},{"src":"assets/chip/2014/7-8-10-5.webp","detailSrc":"assets/chip/2014/detail/7-8-10-5.webp","width":95,"height":105,"pixelWidth":95,"pixelHeight":105,"alt":"Красные и желтоватые ягоды между широкими тёмными листьями."}]},{"number":11,"question":"Расселение рода Homo началось из","choices":["Африки","Австралии","Антарктиды","Северной Америки","Мадагаскара"],"answer":0,"points":4,"title":"Расселение рода Homo","steps":["Одни из древнейших останков представителей рода Homo найдены в Африке. Там же обнаружено много ранних каменных орудий.","Позднее части этих древних популяций вышли в Евразию. Начальный материк — Африка."]},{"number":12,"question":"В России «землю измерить и чертёж государства сделать» впервые повелел","choices":["Михаил Романов","Пётр I","Фёдор III","Иван Грозный","Борис Годунов"],"answer":3,"points":4,"title":"Ранний чертёж государства","steps":["В XVI веке понадобилось свести сведения о дорогах, реках и городах Московского государства. С ранней историей такого картографирования связывают государев наказ при Иване IV.","Иван IV известен как Иван Грозный. Впоследствии карты и словесные описания территории дополняли."]},{"number":13,"question":"«К сумеркам мы дошли до залива Америка», – писал В. К. Арсеньев. Где он путешествовал?","choices":["по Кольскому полуострову","по Приморью","по Аляске","по Калифорнии","по Огненной земле"],"answer":1,"points":4,"title":"Залив с далёким названием","steps":["Путешественник Владимир Арсеньев исследовал российский Дальний Восток. Залив с названием Америка существовал на берегу Японского моря.","Сейчас это залив Находка в Приморье. Старое название не указывает на американский материк."]},{"number":14,"question":"В каком российском регионе находится падь Кулинда, где были обнаружены окаменелые останки юрских динозавров?","choices":["в Алтайском крае","в Приморском крае","в Курганской области","в Забайкальском крае","в Карелии"],"answer":3,"points":4,"title":"Находка в Кулинде","steps":["Возле пади Кулинда найдены кости и отпечатки покровов юрских динозавров. Один описанный по ним вид получил название кулиндадромеус.","Кулинда находится в Забайкальском крае. Находки относятся к российской части Забайкалья."],"adaptation":"Добавлено название конкретного местонахождения окаменелостей."},{"number":15,"question":"Горнолыжник на трассе скоростного спуска использует кривые палки, потому что они","choices":["дают возможность увеличить сопротивление воздуха при спуске","позволяют уменьшить сопротивление воздуха при спуске","помогают судьям чётче фиксировать прохождение спортсмена по трассе","являются атрибутом спортсмена-лыжника","легче, чем прямые"],"answer":1,"points":4,"title":"Лыжные палки на спуске","steps":["На скоростном спуске лыжник приседает и прижимает руки, чтобы силуэт был компактнее. Изогнутые палки лучше располагаются вдоль тела в такой стойке.","Меньше выступающих частей встречают воздушный поток. Это помогает уменьшить сопротивление воздуха."],"figure":{"src":"assets/chip/2014/7-8-15.webp","detailSrc":"assets/chip/2014/detail/7-8-15.webp","width":200,"height":160,"pixelWidth":200,"pixelHeight":160,"alt":"Лыжник на склоне с изогнутыми палками."}},{"number":16,"question":"Первые люди достигли Австралии почти 50 тысяч лет назад. Этому способствовало","choices":["изобретение надувных лодок","узость Баб-эль-Мандебского пролива","замерзание Торресова пролива","низкий уровень океана","Канарское течение"],"answer":3,"points":4,"title":"Первые люди в Австралии","steps":["Во время оледенения часть воды была заключена в ледниках, и уровень океана стоял ниже. Австралия соединялась сушей с Новой Гвинеей.","Некоторые проливы всё равно приходилось пересекать, но осушенные мелководья облегчали часть пути. Подходит низкий уровень океана."]},{"number":17,"question":"Астрономическая весна в Северном полушарии начинается","choices":["28 или 29 февраля","1 марта","в день весеннего равноденствия, примерно 20 марта","1 апреля","1 мая"],"answer":2,"points":4,"title":"Начало астрономической весны","steps":["Астрономическую весну отсчитывают от весеннего равноденствия, когда Солнце проходит через небесный экватор к северу.","Этот момент приходится примерно на 20 марта. Календарная дата зависит от года и часового пояса."],"adaptation":"Исправлен диапазон календарных дат весеннего равноденствия."},{"number":18,"question":"На карте отражён маршрут, который когда-то проходили наши соотечественники. Это","choices":["путь из варяг в греки","Великий шёлковый путь","путь Афанасия Никитина","Чумацкий шлях","Большая Владимирская дорога"],"answer":0,"points":4,"title":"Старинный водный путь","steps":["На карте путь идёт от Балтийского моря к Чёрному по рекам и через участки суши. На Днепре он тянется к Киеву и дальше на юг.","Так суда добирались до Византии. Историческое название — путь из варяг в греки."],"figure":{"src":"assets/chip/2014/7-8-18.webp","detailSrc":"assets/chip/2014/detail/7-8-18.svg","width":480,"height":472,"pixelWidth":550,"pixelHeight":540,"alt":"Карта водного маршрута от Балтийского моря к Чёрному по речной системе Восточной Европы."}},{"number":19,"question":"Это вещество известно человечеству с глубокой древности, но история не сохранила имени его первооткрывателя. Это","choices":["азот","кислород","сера","фосфор","хлор"],"answer":2,"points":4,"title":"Вещество из древности","steps":["Сера встречается в природе в свободном виде, например около вулканических выходов. Её можно было собирать и использовать задолго до современной химии.","Азот, кислород, фосфор и хлор стали описывать как отдельные вещества значительно позже. Из списка вещество, известное в древности, — сера."]},{"number":20,"question":"Первая награда за полёт в космос была вручена Гагарину через несколько часов после приземления. Как называлась эта медаль?","choices":["«За освоение целинных земель»","«За покорение вершин»","«За безупречную службу»","«Золотая Звезда Героя»","Медаль Колумба"],"answer":0,"points":4,"title":"Награда после посадки","steps":["Полёт Юрия Гагарина завершился посадкой в Саратовской области. В день возвращения он получил медаль «За освоение целинных земель».","Медаль «Золотая Звезда» вручали позднее. В вопросе нужна награда, которую Гагарин получил сразу после посадки."]},{"number":21,"question":"У какой страны самая длинная береговая линия по сопоставимым оценкам справочника The World Factbook?","choices":["Австралии","Венгрии","Кубы","США","Филиппин"],"answer":4,"points":5,"title":"Протяжённость берегов","steps":["Островной архипелаг набирает большую суммарную длину берега благодаря множеству отдельных островов. По принятой в справочнике оценке берег Филиппин превышает 36 тысяч километров.","В той же таблице у Австралии около 26 тысяч километров, а у США около 20 тысяч. При этой методике лидируют Филиппины."],"adaptation":"Указана методика, по которой сравниваются береговые линии."},{"number":22,"question":"На гербе Барбадоса изображены животные и растения. Название одного из них дало название и самой стране. Это","choices":["большая корифена","бурый пеликан","сахарный тростник","орхидея «Красная гордость»","бородатый фикус"],"answer":4,"points":5,"title":"Название острова Барбадос","steps":["Название связывают с португальским словом, означающим «бородатые». На острове растут фикусы, у которых с ветвей свисают воздушные корни.","Корни напоминают бороду. С этим деревом связывают название Барбадоса, и его изображение есть на гербе."],"figure":{"src":"assets/chip/2014/7-8-22.webp","detailSrc":"assets/chip/2014/detail/7-8-22.webp","width":200,"height":197,"pixelWidth":200,"pixelHeight":197,"alt":"Герб с двумя животными по бокам щита. На щите показано дерево и цветки, наверху перекрещенные стебли."}},{"number":23,"question":"На границе каких двух плит в школьной схеме лежит Юго-Западный Индийский хребет между Африкой и Антарктидой?","choices":["Евразийской и Тихоокеанской","Североамериканской и Африканской","Антарктической и Южноамериканской","Антарктической и Африканской","Антарктической и Австралийской"],"answer":3,"points":5,"title":"Хребет Индийского океана","steps":["Юго-Западный Индийский хребет идёт между Африкой и Антарктидой. На нём океаническая кора расходится и постепенно нарастает.","В школьной схеме это граница Африканской и Антарктической плит. Выберите именно эту пару."],"adaptation":"Уточнено место границы плит: наличие вулканизма нельзя исключить у подводного хребта."},{"number":24,"question":"В апреле 1682 года француз Рене-Робер Кавелье де Ла Саль достиг устья большой реки и присоединил к небольшой Франции огромную территорию её бассейна. Это была река","choices":["Ориноко","Миссисипи","Нил","Меконг","Нигер"],"answer":1,"points":5,"title":"Река экспедиции Ла Саля","steps":["Ла Саль плыл по большой реке в глубине Северной Америки до её устья в Мексиканском заливе. В 1682 году он объявил бассейн владением французского короля.","Им стала территория, названная Луизианой. Река экспедиции — Миссисипи."]},{"number":25,"question":"Н. М. Пржевальский писал: «В Алашанской пустыне … летом не особенно редко падают дожди», – потому что муссоны приносят сюда влагу с океана","choices":["Атлантического","Индийского","Тихого","Северного Ледовитого","Южного"],"answer":2,"points":5,"title":"Откуда идут летние дожди","steps":["Пустыня Алашань находится в северной части Китая и обычно получает мало дождя. Летом в Восточной Азии усиливается перенос воздуха с моря на сушу.","Часть влаги достигает внутренних районов. В приведённом случае речь о восточноазиатском муссоне с Тихого океана."]},{"number":26,"question":"Полоса сухих (короткотравных прерий) в Северной Америке идёт с севера на юг, а не с запада на восток, потому что","choices":["это соответствует основному пути миграций бизонов и вилорогов","Кордильеры перекрывают путь воздушным массам с Тихого океана","эта территория находилась за пределами распространения ледников","долина Миссисипи способствует вторжению холодного воздуха с севера","эти территории были распаханы, а сейчас здесь идёт восстановление прерий"],"answer":1,"points":5,"title":"Сухая полоса прерий","steps":["Кордильеры вытянуты вдоль запада Северной Америки. Воздух с Тихого океана отдаёт много влаги при подъёме на горы.","За горами остаётся более сухая область. Её меридиональное положение связано с направлением горной цепи."]},{"number":27,"question":"Коренные народы тихоокеанского побережья Канады называют светлую форму одного из этих животных медведем-призраком. Какой снимок её показывает?","choices":["","","","",""],"answer":4,"points":5,"title":"Медведь-призрак","steps":["Светлая особь на снимке Д имеет пропорции американского чёрного медведя и окраску от белой до кремовой. Этот вариант окраски встречается у медведей Кермода на тихоокеанском побережье Канады.","Белого зверя из этой популяции называют медведем-призраком. От арктического белого медведя он отличается и видом, и средой обитания."],"adaptation":"Уточнено, что речь о медведе с тихоокеанского побережья Канады.","optionFigures":[{"src":"assets/chip/2014/7-8-27-1.webp","detailSrc":"assets/chip/2014/detail/7-8-27-1.webp","width":109,"height":105,"pixelWidth":109,"pixelHeight":105,"alt":"Белый медведь на светлом фоне."},{"src":"assets/chip/2014/7-8-27-2.webp","detailSrc":"assets/chip/2014/detail/7-8-27-2.webp","width":111,"height":105,"pixelWidth":111,"pixelHeight":105,"alt":"Чёрно-белый медведь с круглыми ушами."},{"src":"assets/chip/2014/7-8-27-3.webp","detailSrc":"assets/chip/2014/detail/7-8-27-3.webp","width":109,"height":105,"pixelWidth":109,"pixelHeight":105,"alt":"Тёмный медведь со светлой отметиной на груди."},{"src":"assets/chip/2014/7-8-27-4.webp","detailSrc":"assets/chip/2014/detail/7-8-27-4.webp","width":110,"height":105,"pixelWidth":110,"pixelHeight":105,"alt":"Тёмный медведь со светло-бурой мордой и округлыми ушами."},{"src":"assets/chip/2014/7-8-27-5.webp","detailSrc":"assets/chip/2014/detail/7-8-27-5.webp","width":110,"height":105,"pixelWidth":110,"pixelHeight":105,"alt":"Кремовый медведь с тёмным носом и небольшими ушами."}]},{"number":28,"question":"«По длинной зелёной долине, спускающейся к реке, было разбросано десятка два домов, построенных из тяжёлых дубовых брёвен. Дорога шла через мост, потом подымалась на противоположный берег, исчезала в лесных зарослях и, вынырнув, тянулась до замка Мот и дальше, к аббатству Холивуд. Перед деревней, на склоне холма, стояла церковь, окружённая тисовыми деревьями. А кругом, куда ни кинешь взор, тянулись леса, над которыми возвышались вершины зелёных вязов и начинавших зеленеть дубов» (Р.Л. Стивенсон). Описанные в отрывке экосистемы называются","choices":["бореальными","неморальными","антарктическими","гляциальными","подтаёжными"],"answer":1,"points":5,"title":"Лес из отрывка","steps":["В отрывке названы дубы и вязы. Это широколиственные деревья, типичные для лесов умеренного пояса.","Такие леса называют неморальными. Бореальными обычно называют более северные таёжные сообщества."]},{"number":29,"question":"Природным аналогом замка-молнии является","choices":["замок раковины двустворчатых моллюсков","строение молекулы ДНК","строение позвоночного столба млекопитающих","строение жаберного аппарата костных рыб","строение маховых перьев"],"answer":4,"points":5,"title":"Как соединяются части пера","steps":["От стержня махового пера отходят бородки, а от них — более мелкие бородочки. На части бородочек есть крошечные крючки.","Они сцепляются с соседними бородочками и образуют сплошную поверхность. При чистке пера сцепление восстанавливается подобно застёжке."]},{"number":30,"question":"Возле солёного озера Большое Яровое в Алтайском крае установлен","choices":["флюгер","знак о том, что в озере обитают рачки артемии","знак о возможности нашествия саранчи в данной местности","напоминание об опасности клещевого энцефалита, вирус которого переносят иксодовые клещи","памятник вымершим беспозвоночным, ранее здесь обитавшим"],"answer":1,"points":5,"title":"Фигура у озера","steps":["На фотографии модель небольшого водного животного с длинным телом и рядами выростов. На берегу солёного озера эта фигура связана с его обитателями.","В солёной воде живут рачки артемии. Им посвящён установленный у озера знак."],"figure":{"src":"assets/chip/2014/7-8-30.webp","detailSrc":"assets/chip/2014/detail/7-8-30.webp","width":150,"height":232,"pixelWidth":150,"pixelHeight":232,"alt":"У воды стоит металлическая фигура с длинным телом и рядом тонких выростов."}}]);
edition.sources.readers = {"tasksUrl":"assets/chip/2014/7-8_2014-reading.pdf"};
